#include <stdint.h>

#include "stm32f4xx.h"
#include "drv_gpio.h"
#include "boot_shared.h"

/* 1 = saglikliysa bootloader'a onay gonder, 0 = onay gonderme (geri alma testi icin) */
#define APP_CONFIRM_ENABLE   1
/* 1 = 40. yanip sonmede bilerek takil (watchdog testi icin), 0 = normal */
#define APP_SIMULATE_HANG    0

static void app_confirm_if_trial(void)
{
#if APP_CONFIRM_ENABLE
    RCC->APB1ENR |= RCC_APB1ENR_PWREN;     /* yedek register'lara erisim icin */
    (void)RCC->APB1ENR;
    PWR->CR |= PWR_CR_DBP;

    if (RTC->BKP1R == BOOT_STATUS_TRIAL) { /* bootloader "deneme" dedi mi? */
        RTC->BKP0R = BOOT_REQ_CONFIRM;     /* onay istegini birak */
        NVIC_SystemReset();                /* bootloader'a don, o flash'a yazsin */
    }
#endif
}

#define APP_VECTOR_ADDR  0x08020200UL

static void delay(volatile uint32_t n)
{
    while (n--) { }
}


int main(void)
{
	SCB->VTOR = APP_VECTOR_ADDR;   /* kesme tablosu bu uygulamanin tablosu */

	drv_gpio_config(GPIOD, 12U, DRV_GPIO_MODE_OUTPUT, DRV_GPIO_PULL_NONE);
	uint32_t blinks = 0U;

    while (1) {
        drv_gpio_toggle(GPIOD, 12U);   /* yesil LED yanip soner */
        delay(400000U);

        IWDG->KR = 0xAAAAUL;           /* watchdog'u besle: "yasiyorum" */

        blinks++;
        if (blinks == 20U) {               /* ~20 yanip sonme saglikli calistiktan sonra */
            app_confirm_if_trial();
        }
#if APP_SIMULATE_HANG
        if (blinks == 40U) {
            for (;;) { }               /* bilerek takil: besleme kesilir */
        }
#endif

    }
}
